import defaults from './defaults.json'

/*
 * defaults.json is generated by Motet.compileWorld(Motet.defaultRecord): the values of the
 * engine-only properties (material layers, ornament masks, type roles, icon axes) that
 * tokens.json does not carry. A World scope overrides every one of them inline.
 */
const dark = '[data-theme=dark], [data-theme=contrast-dark]'

export const globalCss = {
  ':root': { ...defaults.light, colorScheme: 'light' },
  [dark]: { ...defaults.dark, colorScheme: 'dark' },
  '[data-world][data-mode=dark]': { colorScheme: 'dark' },
  '[data-world][data-mode=light]': { colorScheme: 'light' },

  html: {
    fontFamily: 'var(--font-ui)', color: 'var(--ink)', backgroundColor: 'var(--canvas)',
    WebkitFontSmoothing: 'antialiased', MozOsxFontSmoothing: 'grayscale', textSizeAdjust: '100%',
    scrollPaddingTop: 'calc(var(--chrome-offset, 72px) + 8px)', scrollPaddingBottom: '24px',
  },
  body: { margin: '0', fontSize: '14px', lineHeight: '20px' },
  '::selection': { backgroundColor: 'var(--selection)', color: 'var(--ink)' },

  /* Focus: a solid ring with a 2px gap of whatever surface is behind it. Themes recolour
     it only through the generated --focus, which is held at 3:1 on every surface. */
  ':focus-visible': { outline: '2px solid var(--focus)', outlineOffset: '2px' },
  'button, a, [tabindex]': { '&:focus:not(:focus-visible)': { outline: 'none' } },

  '.m-icon': {
    display: 'inline-block', width: '1em', height: '1em', flex: 'none', overflow: 'hidden',
    fontFamily: 'var(--icon-family)', fontWeight: 'normal', fontStyle: 'normal', fontSize: '20px', lineHeight: '1',
    letterSpacing: 'normal', textTransform: 'none', whiteSpace: 'nowrap', direction: 'ltr', wordWrap: 'normal',
    fontFeatureSettings: '"liga"', userSelect: 'none', speak: 'never',
    fontVariationSettings: '"FILL" 0, "wght" var(--icon-wght), "GRAD" var(--icon-grad), "opsz" 24',
  },
  '.m-icon--fill': { fontVariationSettings: '"FILL" 1, "wght" var(--icon-wght), "GRAD" var(--icon-grad), "opsz" 24' },
  '.m-icon--sm': { fontSize: '16px', fontVariationSettings: '"FILL" 0, "wght" var(--icon-wght), "GRAD" var(--icon-grad), "opsz" 20' },
  '.m-icon--lg': { fontSize: '24px' },

  '.m-visually-hidden': {
    position: 'absolute !important', width: '1px', height: '1px', padding: '0', margin: '-1px', overflow: 'hidden',
    clip: 'rect(0 0 0 0)', whiteSpace: 'nowrap', border: '0',
  },

  /* Reading: the prose of posts and lore. Readers own size and face; Worlds own rhythm. */
  '.m-prose': {
    maxWidth: '68ch', fontFamily: 'var(--font-reading)', fontSize: 'calc(18px * var(--text-scale, 1))', lineHeight: '1.6',
    color: 'var(--ink)', fontVariantNumeric: 'var(--numerals, normal)', overflowWrap: 'break-word', hyphens: 'manual',
    fontOpticalSizing: 'auto', textWrap: 'pretty',
    '& p': { margin: '0' },
    '& p + p': { marginTop: '0.85em' },
    '& em': { fontStyle: 'italic' },
    '& strong': { fontWeight: '650' },
    '& a': { color: 'var(--accent-ink)', textDecorationThickness: '1px', textUnderlineOffset: '0.18em' },
    '& blockquote': {
      margin: '0.9em 0', padding: '10px 14px', backgroundColor: 'var(--surface-quiet)', borderRadius: 'var(--radius-sm)',
      fontSize: '0.94em', color: 'var(--ink)',
      '& cite': { display: 'block', marginTop: '6px', fontFamily: 'var(--font-ui)', fontSize: '13px', fontStyle: 'normal', color: 'var(--ink-muted)' },
    },
    '& ul, & ol': { margin: '0.7em 0', paddingInlineStart: '1.4em' },
    '& ul': { listStyle: 'disc' }, '& ol': { listStyle: 'decimal' },
    '& li::marker': { color: 'var(--ink-muted)' },
    '& li + li': { marginTop: '0.25em' },
    '& hr': { border: '0', height: '1px', margin: '1.4em 20%', backgroundColor: 'var(--line)' },
    '& .ooc': { fontFamily: 'var(--font-ui)', fontSize: '14px', color: 'var(--ink-muted)' },
  },
  '[data-paragraphs=indented] .m-prose p + p': { marginTop: '0', textIndent: '1.6em' },
  '.m-prose--ui': { fontFamily: 'var(--font-ui)', fontSize: 'calc(15px * var(--text-scale, 1))', lineHeight: '1.55' },
  '[data-dropcap=on] .m-prose--lead > p:first-child::first-letter': {
    float: 'left', marginBlock: '0.06em 0', marginInlineEnd: '0.1em', fontFamily: 'var(--font-display)', fontWeight: 'var(--display-weight)',
    fontSize: 'calc(3.3em * var(--display-adjust))', lineHeight: '0.82', color: 'var(--ornament)',
  },

  /* Small shared parts */
  '.m-meta': {
    display: 'inline-flex', alignItems: 'center', gap: '4px', minWidth: '0', fontVariantNumeric: 'tabular-nums',
    '& > .m-icon': { fontSize: '16px' },
  },
  '.m-role': {
    display: 'inline-flex', alignItems: 'center', gap: '3px', height: '20px', paddingInline: '4px 7px', borderRadius: '6px',
    backgroundColor: 'var(--surface-quiet)', boxShadow: 'inset 0 0 0 1px var(--line-strong)', color: 'var(--ink)',
    fontFamily: 'var(--font-ui)', fontSize: '12px', lineHeight: '16px', fontWeight: '600',
    '& .m-icon': { fontSize: '14px' },
  },
  '.m-count': {
    display: 'inline-grid', placeItems: 'center', minWidth: '22px', height: '22px', paddingInline: '6px', borderRadius: '11px',
    backgroundColor: 'var(--surface-quiet)', boxShadow: 'inset 0 0 0 1px var(--line)', color: 'var(--ink)',
    fontFamily: 'var(--font-ui)', fontSize: '12px', fontWeight: '600', fontVariantNumeric: 'tabular-nums',
  },
  '.m-kbd': {
    display: 'inline-grid', placeItems: 'center', minWidth: '22px', height: '22px', paddingInline: '5px', borderRadius: '6px',
    boxShadow: 'inset 0 0 0 1px var(--line-strong), inset 0 -1px 0 var(--line-strong)', font: '500 12px/1 var(--font-mono)', color: 'var(--ink-muted)',
  },

  /* Ornament helpers: corner pieces and flanked headings, both masks in --ornament */
  '.m-ornamented': { position: 'relative' },
  '.m-pad': { padding: 'max(16px, var(--orn-pad, 0px))' },
  '.m-ornamented::after': {
    content: '""', display: 'var(--orn-corner-display, none)', position: 'absolute', inset: '6px', pointerEvents: 'none',
    backgroundColor: 'var(--ornament)',
    maskImage: 'var(--orn-corner-tl), var(--orn-corner-tr), var(--orn-corner-br), var(--orn-corner-bl)',
    maskPosition: 'top left, top right, bottom right, bottom left', maskSize: 'var(--orn-corner-size) var(--orn-corner-size)', maskRepeat: 'no-repeat',
    animation: 'm-fade-in var(--dur-decor) var(--ease-decor) both',
  },
  '.m-flanked': { display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '14px' },
  '.m-flanked::before, .m-flanked::after': {
    content: '""', display: 'var(--orn-flank-display, none)', flex: 'none', width: 'var(--orn-flank-w)', height: 'var(--orn-flank-h)',
    backgroundColor: 'var(--ornament)', maskImage: 'var(--orn-flank)', maskSize: 'contain', maskRepeat: 'no-repeat', maskPosition: 'center',
  },
  '.m-flanked::after': { transform: 'scaleX(-1)' },

  /* Segment mark: a short bar riding the top edge of framed surfaces (Worlds with the
     segment ornament at level 2+). It replaces corner pieces for hard-edged styles. */
  '.m-marked': { position: 'relative' },
  '.m-marked::before': {
    content: '""', display: 'var(--orn-mark-display, none)', position: 'absolute', zIndex: '1', pointerEvents: 'none',
    top: 'calc(-1 * var(--border-width, 1px))', insetInlineStart: '24px', width: '44px', height: '3px',
    backgroundColor: 'var(--ornament)',
  },
  ':is([data-post=open], [data-post=log]) .m-post__root.m-marked::before, .m-post__root--lane_ooc.m-marked::before': { display: 'none' },

  /* Dice faces come from DiceFont (SIL OFL 1.1, Franco Ponticelli) */
  '.m-die': {
    fontFamily: 'var(--font-dice)', fontWeight: '400', fontStyle: 'normal', lineHeight: '1', letterSpacing: '0',
    textTransform: 'none', fontFeatureSettings: 'normal', speak: 'never', userSelect: 'none',
  },

  /* High contrast: controls and quiet surfaces are set apart by borders, not by shade alone */
  ':is([data-theme^=contrast], [data-contrast=high])': {
    '& :is(.m-button--variant_tonal, .m-button--variant_text)': { borderColor: 'var(--line-strong) !important' },
    '& :is(.m-icon-button--variant_tonal, .m-chip--kind_note, .m-chip--kind_fact, .m-flag, .m-alert__root, .m-tags__tag, .m-collapsible__root--variant_spoiler)': { boxShadow: 'inset 0 0 0 1px var(--line-strong) !important' },
    '& :is(.m-segmented__root, .m-post__root--lane_ooc, .m-roll__root, .m-character__root, .m-composer__root)': { outline: '1px solid var(--line-strong) !important', outlineOffset: '-1px' },
  },

  /* Motion: state and route changes run as view transitions (Motet.transition, and @view-transition
     for full page loads). Groups move on the spatial spring and images cross-fade on the effects
     spring. Something on one side of a change only rises in, or settles out, instead of cross-fading.
     Directional changes (a step forward, a drill-in) name their swapped region m-pane and pass a
     type, 'forward' or 'back', which Motet also writes to <html data-vt>. Panda can't emit the
     @view-transition at-rule, so it lives in raw.css, appended after cssgen. */
  '::view-transition-group(*)': { animationDuration: 'var(--dur-spatial-default)', animationTimingFunction: 'var(--ease-spatial-default)' },
  '::view-transition-old(*), ::view-transition-new(*)': { animationTimingFunction: 'var(--ease-effects-default)' },
  '::view-transition-new(*):only-child': { animation: 'm-vt-enter var(--dur-spatial-default) var(--ease-spatial-default) both' },
  '::view-transition-old(*):only-child': { animation: 'm-vt-exit var(--dur-effects-fast) var(--ease-effects-fast) both' },
  'html[data-vt~=forward]::view-transition-old(m-pane)': { animation: 'm-vt-out-start var(--dur-effects-default) var(--ease-effects-default) both' },
  'html[data-vt~=forward]::view-transition-new(m-pane)': { animation: 'm-vt-in-end var(--dur-spatial-default) var(--ease-spatial-default) both' },
  'html[data-vt~=back]::view-transition-old(m-pane)': { animation: 'm-vt-out-end var(--dur-effects-default) var(--ease-effects-default) both' },
  'html[data-vt~=back]::view-transition-new(m-pane)': { animation: 'm-vt-in-start var(--dur-spatial-default) var(--ease-spatial-default) both' },
  /* stacking while things move: the chrome stays on top, the composer passes over what appears
     behind it, and text moving out of the composer passes over both */
  '::view-transition-group(m-chrome-start), ::view-transition-group(m-chrome-end)': { zIndex: '10' },
  '::view-transition-group(m-composer)': { zIndex: '2' },
  '::view-transition-group(m-draft)': { zIndex: '3' },
  /* 'filter': a list changes what it shows. The page can get shorter and scroll, so the page
     underneath swaps at once and only the named items move, instead of two scroll positions
     cross-fading */
  'html[data-vt~=filter]::view-transition-old(root)': { display: 'none' },
  'html[data-vt~=filter]::view-transition-new(root)': { animation: 'none' },
  /* in a directional change, whatever leaves goes the way the pane goes */
  'html[data-vt~=forward]::view-transition-old(*):only-child': { animation: 'm-vt-out-start var(--dur-effects-default) var(--ease-effects-default) both' },
  'html[data-vt~=forward]::view-transition-new(*):only-child': { animation: 'm-vt-in-end var(--dur-spatial-default) var(--ease-spatial-default) both' },
  'html[data-vt~=back]::view-transition-old(*):only-child': { animation: 'm-vt-out-end var(--dur-effects-default) var(--ease-effects-default) both' },
  'html[data-vt~=back]::view-transition-new(*):only-child': { animation: 'm-vt-in-start var(--dur-spatial-default) var(--ease-spatial-default) both' },
  /* a die that has just been rolled tumbles in once */
  '::view-transition-new(m-die):only-child': { animation: 'm-die-in var(--dur-spatial-slow) var(--ease-spatial-slow) both' },
  /* Names apply only while a transition runs (Motet.transition sets <html data-vt>; full page loads
     match :active-view-transition). A named element is a stacking context and a backdrop root,
     so a permanent name would cut frosted menus off from what is behind them and lift posts over
     each other's menus. .m-vt takes its name from --vt, for lists whose items each need one. */
  ':is(html[data-vt], html:active-view-transition) .m-vt': { viewTransitionName: 'var(--vt)' },
  ':is(html[data-vt], html:active-view-transition) .m-vt-pane': { viewTransitionName: 'm-pane' },
  /* a pane that slides moves as one piece: named things inside it stay part of it */
  ':is(html[data-vt~=forward], html[data-vt~=back]) .m-vt-pane :is(.m-vt, .m-composer__root)': { viewTransitionName: 'none' },
  /* .m-vt-box: a card or row whose shape changes (a card becoming a list row, a request becoming
     its result). Its content keeps its size and is uncovered or cut by the moving box, instead of
     being stretched to fit. Shared parts inside it (a portrait, a name) carry their own .m-vt. */
  ':is(html[data-vt], html:active-view-transition) .m-vt-box': { viewTransitionClass: 'm-box' },
  '::view-transition-old(*.m-box), ::view-transition-new(*.m-box)': { width: '100%', height: '100%', objectFit: 'none', objectPosition: 'left top' },
  ':is(html[data-vt], html:active-view-transition) .m-chrome__island:first-child': { viewTransitionName: 'm-chrome-start' },
  ':is(html[data-vt], html:active-view-transition) .m-chrome__island:last-child': { viewTransitionName: 'm-chrome-end' },
  ':is(html[data-vt], html:active-view-transition) .m-masthead__mark': { viewTransitionName: 'm-world-mark' },
  ':is(html[data-vt], html:active-view-transition) .m-masthead__title': { viewTransitionName: 'm-world-title' },
  ':is(html[data-vt], html:active-view-transition) .m-composer__root': { viewTransitionName: 'm-composer' },

  /* Side menu and content (Settings, Manage). Wide: side by side. Below 900px it becomes a drill-in:
     the menu, then the chosen section with a back button; data-pane says which is showing.
     Moving between them is a 'forward' or 'back' transition of the m-pane region. */
  '.m-drill__back': { display: 'none !important' },
  '@media (max-width: 899px)': {
    '.m-drill[data-pane=nav] > .m-drill__content, .m-drill[data-pane=content] > .m-drill__nav': { display: 'none !important' },
    '.m-drill__back': { display: 'inline-flex !important', alignSelf: 'flex-start', marginInlineStart: '-8px', marginBottom: '-12px' },
  },

  /* A row of chips or tabs that scrolls sideways on narrow screens instead of wrapping. Where
     scroll-driven animation exists, the edges fade only on the side that has more to show. */
  '.m-scroll-row': {
    display: 'flex', flexWrap: 'nowrap', gap: '8px', overflowX: 'auto', overscrollBehaviorX: 'contain', scrollbarWidth: 'none',
    paddingBlock: '2px', marginBlock: '-2px', scrollPaddingInline: '24px',
    '& > *': { flexShrink: '0' },
    '&::-webkit-scrollbar': { display: 'none' },
  },
  '@supports (animation-timeline: scroll())': {
    '.m-scroll-row, .m-tabs__root': {
      maskImage: 'linear-gradient(to right, transparent, #000 var(--m-fade-start), #000 calc(100% - var(--m-fade-end)), transparent)',
      animation: 'm-scroll-fade linear both', animationTimeline: 'scroll(self inline)',
    },
  },
  '@media (prefers-reduced-motion: reduce)': {
    ':root, [data-world]': {
      '--dur-spatial-fast': '0ms !important', '--dur-spatial-default': '0ms !important', '--dur-spatial-slow': '0ms !important',
      '--dur-decor': '0ms !important',
    },
    '::view-transition-group(*), ::view-transition-old(*), ::view-transition-new(*)': { animation: 'none !important' },
  },
  '[data-reduce-motion], [data-reduce-motion] [data-world]': {
    '--dur-spatial-fast': '0ms !important', '--dur-spatial-default': '0ms !important', '--dur-spatial-slow': '0ms !important', '--dur-decor': '0ms !important',
  },

  /* Forced colours: material, grain and ornament disappear; borders carry separation */
  '@media (forced-colors: active)': {
    '.m-post__root, .m-composer__root, .m-character__root, .m-chrome__island, .m-roll__root, .m-menu__root, .m-dialog__root': {
      border: '1px solid CanvasText !important', backgroundImage: 'none !important',
    },
    '.m-ornamented::after, .m-flanked::before, .m-flanked::after, .m-marked::before, .m-divider__motif, .m-world__backdrop, .m-masthead__art::before': { display: 'none !important' },
    '.m-world__root::before': { maskImage: 'none !important' },
    '.m-divider__line': { backgroundColor: 'CanvasText !important', backgroundImage: 'none !important' },
    '.m-scene-row__marker, .m-inbox-item__root::before': { backgroundColor: 'Highlight !important' },
    '.m-checkbox__control, .m-radio__control': { forcedColorAdjust: 'none', borderColor: 'CanvasText', backgroundColor: 'Canvas' },
    '.m-checkbox__control:is(:checked, :indeterminate)': { backgroundColor: 'Highlight', borderColor: 'Highlight' },
    '.m-checkbox__control::after': { backgroundColor: 'HighlightText' },
    '.m-radio__control:checked': { borderColor: 'Highlight' },
    '.m-radio__control::after': { backgroundColor: 'Highlight' },
    '.m-progress__fill, .m-ring__arc': { forcedColorAdjust: 'none', backgroundColor: 'Highlight', stroke: 'Highlight' },
    '.m-calendar__day[aria-selected=true], .m-listbox__option[data-active], .m-tree__item[aria-selected=true] > .m-tree__row, .m-pagination__page[aria-current=page]': { forcedColorAdjust: 'none', backgroundColor: 'Highlight !important', color: 'HighlightText !important' },
    '.m-skeleton, .m-alert__root, .m-toast__root, .m-popover__root, .m-hovercard__root, .m-listbox__root, .m-calendar__popup, .m-drawer__root': { border: '1px solid CanvasText' },
  },
}

export const keyframes = {
  'm-fade-in': { from: { opacity: '0' } },
  /* parallax: fixed art rises over the first screen of scrolling; header art sinks as it scrolls away */
  'm-drift-up': { to: { translate: '0 calc(var(--art-parallax, 0) * -50vh)' } },
  'm-drift-down': { to: { translate: '0 calc(var(--art-parallax, 0) * 50%)' } },
  'm-drawer-in': { from: { translate: '100% 0' } },
  'm-sheet-in': { from: { translate: '0 100%' } },
  'm-indeterminate': { from: { translate: '-100% 0' }, to: { translate: '300% 0' } },
  'm-spin': { from: { rotate: '-90deg' }, to: { rotate: '270deg' } },
  'm-dialog-in': { from: { opacity: '0', scale: '0.96' } },
  'm-rise': { from: { opacity: '0', translate: '0 8px' } },
  'm-vt-enter': { from: { opacity: '0', translate: '0 6px' } },
  'm-vt-exit': { to: { opacity: '0', scale: '0.98' } },
  'm-vt-out-start': { to: { opacity: '0', translate: '-24px 0' } },
  'm-vt-in-end': { from: { opacity: '0', translate: '24px 0' } },
  'm-vt-out-end': { to: { opacity: '0', translate: '24px 0' } },
  'm-vt-in-start': { from: { opacity: '0', translate: '-24px 0' } },
  'm-die-in': { from: { opacity: '0', scale: '0.4', rotate: '-150deg' } },
  'm-scroll-fade': {
    '0%': { '--m-fade-start': '0px', '--m-fade-end': '28px' },
    '12%, 88%': { '--m-fade-start': '28px', '--m-fade-end': '28px' },
    '100%': { '--m-fade-start': '28px', '--m-fade-end': '0px' },
  },
}
